const EXPECTED_TOPIC = "REPLACE_WITH_UNIQUE_TOPIC_ROOT/data";
const EXPECTED_DEVICE = "REPLACE-WITH-DEVICE-ID";
const badRange = msg.payload === "bad-range";

msg.topic = EXPECTED_TOPIC;
msg.demo = true;
msg.payload = JSON.stringify({
    v: 1,
    device: EXPECTED_DEVICE,
    seq: 1,
    ts: Math.floor(Date.now() / 1000),
    temp: badRange ? 120 : 26.4,
    humi: 63.0,
    light: 2048,
    status: "ok"
});
return msg;

const MAX_JSON_BYTES = 384;
const receivedAt = Date.now();

function reject(code, detail, bytes) {
    const validation = {
        ok: false,
        code,
        detail,
        checked_at: new Date(receivedAt).toISOString()
    };
    if (Number.isInteger(bytes)) validation.bytes = bytes;
    node.status({ fill: "red", shape: "ring", text: code });
    return [null, { validation, demo: msg.demo === true }];
}

if (typeof msg.payload !== "string") {
    return reject("PAYLOAD_TYPE", "payload must be a UTF-8 string");
}

const bytes = Buffer.byteLength(msg.payload, "utf8");
if (bytes < 1 || bytes > MAX_JSON_BYTES) {
    return reject("PAYLOAD_SIZE", "payload must be 1..384 UTF-8 bytes", bytes);
}

msg._receivedAt = receivedAt;
msg._payloadBytes = bytes;
node.status({ fill: "blue", shape: "dot", text: bytes + " B" });
return [msg, null];

const EXPECTED_TOPIC = "REPLACE_WITH_UNIQUE_TOPIC_ROOT/data";
const EXPECTED_DEVICE = "REPLACE-WITH-DEVICE-ID";
const MIN_VALID_EPOCH = 1700000000;
const MAX_FUTURE_SECONDS = 5;
const MAX_AGE_SECONDS = 10;
const checkedAt = Math.floor(Date.now() / 1000);
const bytes = msg._payloadBytes;

function reject(code, detail, age) {
    const validation = {
        ok: false,
        code,
        detail,
        checked_at: new Date(checkedAt * 1000).toISOString()
    };
    if (Number.isInteger(bytes)) validation.bytes = bytes;
    if (Number.isInteger(age)) validation.age_s = age;
    node.status({ fill: "red", shape: "ring", text: code });
    return [null, { validation, demo: msg.demo === true }];
}

if (msg.topic !== EXPECTED_TOPIC) {
    return reject("TOPIC_MISMATCH", "msg.topic does not match EXPECTED_TOPIC");
}

const p = msg.payload;
if (p === null || typeof p !== "object" || Array.isArray(p)) {
    return reject("PAYLOAD_TYPE", "JSON root must be an object");
}

const expectedFields = ["device", "humi", "light", "seq", "status", "temp", "ts", "v"];
const actualFields = Object.keys(p).sort();
if (actualFields.length !== expectedFields.length ||
    actualFields.some((key, index) => key !== expectedFields[index])) {
    return reject("FIELDS", "schema must contain exactly the eight v1 fields");
}
if (!Number.isSafeInteger(p.v) || p.v !== 1) {
    return reject("VERSION", "v must be safe integer 1");
}
if (typeof p.device !== "string" || !/^[A-Za-z0-9-]{1,23}$/.test(p.device)) {
    return reject("DEVICE_FORMAT", "device must be 1..23 alphanumeric or hyphen characters");
}
if (p.device !== EXPECTED_DEVICE) {
    return reject("DEVICE_MISMATCH", "device does not match EXPECTED_DEVICE");
}
if (!Number.isSafeInteger(p.seq) || p.seq < 1 || p.seq > 4294967295) {
    return reject("SEQ", "seq must be safe integer 1..4294967295");
}
if (!Number.isSafeInteger(p.ts) || p.ts <= MIN_VALID_EPOCH) {
    return reject("TIME_INVALID", "ts must be Unix seconds greater than 1700000000");
}
if (typeof p.temp !== "number" || !Number.isFinite(p.temp) || p.temp < -20 || p.temp > 80) {
    return reject("TEMP_RANGE", "temp must be finite number -20..80");
}
if (typeof p.humi !== "number" || !Number.isFinite(p.humi) || p.humi < 0 || p.humi > 100) {
    return reject("HUMI_RANGE", "humi must be finite number 0..100");
}
if (!Number.isInteger(p.light) || p.light < 0 || p.light > 4095) {
    return reject("LIGHT_RANGE", "light must be integer 0..4095");
}
if (typeof p.status !== "string" || p.status !== "ok") {
    return reject("STATUS", "status must be string ok");
}

const age = checkedAt - p.ts;
if (age < -MAX_FUTURE_SECONDS) {
    return reject("TIME_FUTURE", "ts is more than 5 seconds in the future", age);
}
if (age > MAX_AGE_SECONDS) {
    return reject("STALE", "age exceeds 10 seconds", age);
}

msg.payload = { ...p };
msg.validation = { ok: true, code: "OK", bytes, age_s: age };
delete msg._receivedAt;
delete msg._payloadBytes;
node.status({ fill: "green", shape: "dot", text: "OK age " + age + "s" });
return [msg, null];

const checkedAt = Date.now();
const validation = {
    ok: false,
    code: "JSON_PARSE",
    detail: "JSON syntax rejected; raw payload suppressed",
    checked_at: new Date(checkedAt).toISOString()
};
if (Number.isInteger(msg._payloadBytes)) validation.bytes = msg._payloadBytes;
node.status({ fill: "red", shape: "ring", text: "JSON_PARSE" });
return { validation, demo: msg.demo === true };
